import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第03章 数学卷子","description":"","frontmatter":{},"headers":[],"relativePath":"第03章_数学卷子.md","filePath":"第03章_数学卷子.md"}'),r={name:"第03章_数学卷子.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第03章-数学卷子" tabindex="-1">第03章 数学卷子 <a class="header-anchor" href="#第03章-数学卷子" aria-label="Permalink to &quot;第03章 数学卷子&quot;">​</a></h1><p>腊月里雨下了三天。</p><p>南雾县的冬天是湿的，冷从脚底往上爬，屋子里比外头还阴。奶奶那台收音机不出声有些日子了。她每天傍晚还是把它打开，坐在旁边择菜，开着，像听，又像不听。我问她坏了多久，她说记不清了，反正好久了。</p><p>我把它拆开。外壳是深棕色的，边角磨得发亮，后盖上贴着半张早就褪了色的标签，上面印的字看不太清了。里面全是灰，我用毛笔把灰扫出来，扫成一小堆。有一根线断了，线头翘着，不知道是什么时候断的。</p><p>焊枪是爷爷留下来的，笔杆上缠着两圈胶布。我插上电，等半分钟，锡化开的时候有一股松香的味道，呛，但是不难受。外面的雨敲在阳台的铁皮上，咚咚的，一下一下，跟锡焊的声音搅在一起。</p><p>她在这时候发来消息。</p><p>「数学是什么鬼东西」</p><p>我放下焊枪，回了三个字：怎么了。</p><p>她没回。过了两分钟，又来一条。</p><p>「考砸了」</p><p>我问，多少。</p><p>她说，你别问。</p><p>我说，好。</p><p>然后她开始骂。一条接一条，短得很，像把一口气分成了十几截。骂题目出的变态，骂出卷的老师手欠，骂自己的脑子在考场上当场停摆。</p><p>中间她发来一句：「我为什么 我靠 悟了 9是3² 我把他当成2³」</p><p>我把这句话看了两遍，回她：9 是 3 的平方，是对的。</p><p>隔了几秒，她回：他妈的 答案是9我写的8</p><p>我说，那不就差一分。</p><p>她说，差一分也是错。</p><p>我本想给她讲那道题。我拿过草稿纸，画了个图，写了两行，又觉得她未必想看，停住了。结果她自己接了一句：你别念了。</p><p>我说，好。</p><p>隔了半分钟，她忽然又发来一条，跟数学完全没关系。</p><p>「我今天看到一个视频，有人把手机掉进火锅里，捞出来还在用」</p><p>我说，那手机挺结实。</p><p>她说，不是，是火锅不烫。她顿了一下，补一句：反正你也看不懂。</p><p>我说，嗯，看不懂。</p><p>她说：你就知道嗯。</p><p>我说，那我换个字。</p><p>她过了很久没说话。我以为她真生气了，正想解释，她发来：算了。</p><p>又过了几分钟，她问，你在干嘛。</p><p>我说，修收音机。</p><p>她说，你还会修这个。</p><p>我说，坏了就修。</p><p>她说，你家里的事是不是都是你干。</p><p>我说，差不多。</p><p>她说，那你会做饭吗。</p><p>我说，会一点。</p><p>她说，那挺好。</p><p>她说完这句又停了。雨小了一点。我低头继续焊那根线，锡凝住的地方鼓起一个小圆点，反着光。我焊完，接上电，试了一下。喇叭还是不出声。</p><p>我去倒了杯水，回来的时候，屏幕上多了一行字。</p><p>「你陪我说说话」</p><p>我把杯子放下。那台收音机还摊在桌上，后盖朝上，像个翻过来的壳。</p><p>我说，我在。</p><p>她说，今天我把我妈气到了。</p><p>我说，怎么了。</p><p>她说，卷子发下来，她先看分数，看完把卷子扔在地上。</p><p>我说，扔地上了？</p><p>她说，嗯。</p><p>我打字，删了，又打。</p><p>最后我说，那你捡起来了吗。</p><p>她说，捡了。她让我捡的。</p><p>隔了一会儿，她又发来一条。</p><p>她说，我妹考了八十几。</p><p>我盯着这句话看。她没说别的，就这一句。我那时候还不懂她为什么要提她妹妹，只觉得这句话跟前面那些骂人的话不是一个质地，它太干净了，干净得有点冷。</p><p>我说，嗯。</p><p>她说，行了，不说了。</p><p>我说，好。</p><p>她说，你别学我骂人。</p><p>我说，我不骂。</p><p>她说，你骂得出来才怪。</p><p>雨小下去了。奶奶在厨房喊我吃饭。我说来了，手上还带着松香的味道，洗了两遍才下去。</p><p>饭桌上一荤一素，奶奶把荤的都往我碗里拨。我说够了，她说长身体。吃到一半我问她，收音机是爷爷买的吗。</p><p>她愣了一下，说是，那年买的，花了小半个月的工资。</p><p>我说，我修好了再给你。</p><p>她说，修不好就算了，放着也是放着。</p><p>我说，放着占地方。</p><p>她说，占就占着，不碍事。</p><p>我没说话，低头扒饭。奶奶吃饭很慢，牙不好，一口要嚼很久。窗外有人推车经过，轮子压过积水，哗的一声。</p><p>吃完饭我又回桌上试那台收音机。这回我换了个地方查，接上电，拨开关。喇叭里滋滋响了一声，接着出来一段听不懂的话，像是什么地方的口音，念得很快，一句接一句，很有精神。</p><p>我把音量拧小，凑过去听。</p><p>听了半天听不出来是什么，就把开关关了。屋里一下子静下来，静得能听见奶奶在里屋翻身。</p><p>过了一会儿她起来了，去倒水。我把收音机搬给她看，说能响了。她凑过来看了一眼，说，怎么是个说书的。我说，大概是。她说，你爷爷以前就爱听这个，听完还要讲给我听，讲得颠三倒四的。</p><p>我说，那现在呢。她说，现在没人讲了。</p><p>手机又亮了。</p><p>是她的转账。二十块。</p><p>我问，干嘛。</p><p>她说，拿去修你的零件。</p><p>我说，不用。</p><p>她说，收着。</p><p>我说，真不用。</p><p>她说，你是不是嫌少。</p><p>我说，不是。</p><p>她过了很久没回。我以为她生气了，正准备解释，她发来一句：那你收着，就当我今天没说那些话。</p><p>我把那二十块收了。</p><p>收完我看着屏幕，忽然想跟她说点什么。我打了一句：我修收音机的时候，也常修不好。</p><p>打完觉得没意思，删了。</p><p>又打一句：你骂人的时候，比说家里的事好听。</p><p>打完觉得更没意思，也删了。</p><p>再打一句：你妹妹考多少分，跟你没关系。</p><p>这句我自己看着都别扭，也删了。</p><p>最后我发给她的是三个字：早点睡。</p><p>她回：嗯 你也是。</p><p>隔了两分钟，又来一条。</p><p>她说，今天谢谢你听我说话。</p><p>我说，随时。</p><p>她发来一个表情。是一张脸，耷拉着，像要谢的花。</p><p>那天晚上我把收音机后盖装回去，螺丝拧了三颗，缺一颗，就先空着。奶奶已经睡了，客厅只开了一盏小的。我坐在那儿想，她妹妹考了八十几，她考砸了，卷子被扔在地上。</p><p>这两件事之间，一定还有什么她没说。</p><p>我那时候想的是，等她愿意说的时候再说。</p><p>我现在知道，她那天说的已经是全部了。她只是把它说得像句闲话。</p>',100)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
